  const pointsString = points.map(p => `${p.x},${p.y}`).join(' ');

  return (
    <div style={{ display: 'flex', gap: '20px', padding: '20px', fontFamily: 'sans-serif' }}>
      <div style={{ position: 'relative' }}>
        <h3>Click to add points</h3>
