          {/* Draw small circles at each vertex for better visibility */}
          {points.map((p, i) => (
            <circle key={i} cx={p.x} cy={p.y} r="4" fill="red" />
          ))}

          {/* If closed, draw a polygon to fill the shape */}
          {isClosed && (
            <polygon
              points={pointsString}
              fill="rgba(0, 0, 255, 0.2)"
              stroke="blue"
              strokeWidth="3"
            />
          )}
        </svg>

        <div style={{ marginTop: '10px' }}>
          <button onClick={closeShape} disabled={isClosed}>Close Shape</button>
          <button onClick={resetCanvas} style={{ marginLeft: '10px' }}>Clear</button>
        </div>
      </div>

      <div style={{ width: '200px', borderLeft: '1px solid #ccc', paddingLeft: '20px' }}>
        <h4>Vertices List</h4>
        <ul style={{ fontSize: '12px' }}>
