### 1. Database Configuration (`config/db.js`)
We create a connection pool here. Using a `pool` is better than a single `connection` because it handles multiple simultaneous requests efficiently.

```javascript
const mysql = require('mysql2');

const pool = mysql.createPool({
  host: 'localhost',
  user: 'root',
  password: 'password',
  database: 'hotel_db',
  waitForConnections: true,
  connectionLimit: 10,
  queueLimit: 0
});

// Export the promise-based pool for easier async/await usage
module.exports = pool.promise();
```

### 2. The Model (`models/hotelModel.js`)
The model is the only place that should contain raw SQL queries.

```javascript
const db = require('../config/db');

class Hotel {
  static async findByName(name) {
    // Use parameterized queries (?) to prevent SQL Injection attacks
    const sql = 'SELECT * FROM hotels WHERE name LIKE ?';
    const searchTerm = `%${name}%`;

    const [rows] = await db.execute(sql, [searchTerm]);
    return rows;
  }
}

module.exports = Hotel;
```

### 3. The Controller (`controllers/hotelController.js`)
The controller handles the request and response. It calls the model to get data and decides what to send back to the client.

```javascript
const Hotel = require('../models/hotelModel');

exports.searchHotels = async (req, res) => {
  try {
    const { name } = req.query;

    if (!name) {
      return res.status(400).json({ message: "Query parameter 'name' is required" });
    }

    const hotels = await Hotel.findByName(name);
    res.status(200).json(hotels);
  } catch (error) {
    console.error("Error searching hotels:", error);
    res.status(500).json({ message: "Internal Server Error" });
  }
};
```

