    private String doneWell = "Great teamwork!";
    private String improvements = "Needs to improve punctuality.";
    private String others = "Interested in learning Python.";

    public CategorizedCommentsDecorator(Evaluation evaluation) {
        super(evaluation);
    }

    @Override
    public String getReport() {
        // It calls the original report AND adds the new categorized comments
        return super.getReport() + 
               "\n[Done Well]: " + doneWell + 
               "\n[Improvements]: " + improvements + 
               "\n[Others]: " + others;
    }
}
```

